// SetRefreshInterval changes the per-feed polling interval (in minutes).
// When a new non-zero interval is set, the next check is moved earlier if needed,
// so that the new interval takes effect without waiting for the previous schedule.
// @effects: mut
func (f *Feed) SetRefreshInterval(minutes int) {
	if minutes < 0 {
		minutes = 0
	}
	if minutes == f.RefreshInterval {
		return
	}
	f.RefreshInterval = minutes
	if minutes > 0 {
		candidate := f.CheckedAt.Add(time.Duration(minutes) * time.Minute)
		if candidate.Before(f.NextCheckAt) {
			f.NextCheckAt = candidate
		}
	}
}

